import os
import json
from pathlib import Path

# Read both policy documents
policy_files = []
for file in os.listdir('.'):
    if file.endswith('.json') and 'policy' in file.lower():
        policy_files.append(file)

print(f"Found policy files: {policy_files}")

policies = {}
for policy_file in policy_files:
    try:
        with open(policy_file, 'r') as f:
            policies[policy_file] = json.load(f)
        print(f"Successfully loaded {policy_file}")
    except Exception as e:
        print(f"Error loading {policy_file}: {e}")

# Analyze policies to determine authoritative one
if len(policies) == 0:
    print("No policy files found")
elif len(policies) == 1:
    print(f"Only one policy found: {list(policies.keys())[0]}")
    print("This is the authoritative policy by default")
else:
    print("\nAnalyzing multiple policies...")

    # Check for version information
    for filename, policy in policies.items():
        print(f"\n{filename}:")
        if 'version' in policy:
            print(f"  Version: {policy['version']}")
        if 'effective_date' in policy:
            print(f"  Effective Date: {policy['effective_date']}")
        if 'authority' in policy:
            print(f"  Authority: {policy['authority']}")

    # Determine authoritative policy based on common indicators
    authoritative = None
    reasons = []

    for filename, policy in policies.items():
        # Check for explicit authority indicators
        if policy.get('is_authoritative', False):
            authoritative = filename
            reasons.append("Explicit 'is_authoritative' flag")
            break

        # Check for latest version
        if 'version' in policy:
            if not authoritative or policy['version'] > policies[authoritative].get('version', '0'):
                authoritative = filename
                reasons.append("Latest version")

    if authoritative:
        print(f"\nAuthoritative policy determined: {authoritative}")
        print(f"Reason(s): {', '.join(reasons)}")
    else:
        print("\nCould not determine authoritative policy automatically")
        print("Please review the policies manually")
